import { ReactNode, useEffect, useState } from 'react';
import CustomPreviewRight from '@/components/CustomPage/Preview/right';
import { Button, Tabs, Space, Spin, Message, Empty, Modal, Dropdown, Menu, Checkbox } from '@arco-design/web-react';
import styles from './index.module.less';
import Store from './store';
import { AsyncButton, MyErrorBoundary } from '@/components/custom';
import { useObserver } from 'mobx-react-lite';;
import { MonacoCode } from '@/components/MonacoEditor';
import { IconPlus, IconSync } from '@arco-design/web-react/icon';
import { AddModule } from '@/components/ModuleList';
import { moduleStore } from 'react-converter-code';
import classNames from 'classnames';
import { IfrmaeAppProps } from '@/types/iframe';
import file from "@/store/file";
import app from "@/store/app";
import language from '@/store/language'
import pageStore from "@/store/page";
import AppIframe from './AppIframe';
import type FileStore from "@/components/MonacoEditor/code/Contents/fileStore";
import message from './message';
import plugins from '@/store/plugins';


interface TreeNameProps {
    title: string | ReactNode;
    fileStore: FileStore;
}
const TreeName = ({ title, fileStore }: TreeNameProps) => {

    return useObserver(() => {
        return (
            <Spin loading={fileStore.loading}>
                <div
                    className={classNames({
                        [styles.isEdit]: fileStore.isEdit,
                        [styles.fileName]: true
                    })}
                >
                    <span className={styles.title}>{title}</span>
                    <span className={styles.dot}></span>
                </div>
            </Spin>
        )
    })
}

const { TabPane } = Tabs;

export default () => {

    const [store] = useState(() => new Store());
    useEffect(() => {
        message.init();
        return () => {
            message.unInit();
        }
    },[])


    return useObserver(() => {

        const [visible, setVisible] = useState<boolean>(false);
        const [pageVisible, setPageVisible] = useState<boolean>(false);

        useEffect(() => {
            if (store.mode === "code") {
                const onKeyDown = (event) => {
                    // 检查按下的键是否是 "C" 和 "S" 键
                    if (event.key === 's' && (event.ctrlKey || event.metaKey)) {
                        // 用户按下 "s" 键和 ctrl 键
                        // 这里可以执行您想要的操作，比如触发购物车事件
                        event.preventDefault();
                        store.syncUpddatePageStore()
                        // 请将您的购物车逻辑放在这里
                    }
                }
                document.addEventListener('keydown', onKeyDown);
                return () => {
                    document.removeEventListener('keydown', onKeyDown);
                    store.unInit();
                }
            }

            return () => {
                store.unInit();
            }

        }, [store.mode])

        return (
            <div className={`${styles.page}`}>
                <MonacoCode
                    store={store.code}
                    contentProps={{
                        renderTitle:({ title, dataRef, ...props }) => {
                            const fileStore: any = dataRef.uri && store.code.fileStores[dataRef.uri.path];
                            if(fileStore){
                                return (
                                    <TreeName key={dataRef.key} title={title} fileStore={fileStore} />
                                )
                            }else if(title == 'components' || title == 'pages'){
                                return (
                                    <div className="flex items-center justify-between w-full">
                                        <span>{title}</span>
                                        <IconPlus
                                            className="text-blue-500"
                                            onClick={(e) => {
                                                e.preventDefault();
                                                e.stopPropagation();
                                                if(title == 'components'){
                                                    setVisible(true);
                                                }else if(title == 'pages'){
                                                    setPageVisible(true);
                                                }
                                            }}
                                        />
                                    </div>
                                )
                            }else if(title == 'public'){
                                return (
                                    <div className="flex items-center justify-between w-full">
                                        <span>{title}</span>
                                        <IconSync
                                            className="text-blue-500"
                                            onClick={(e) => {
                                                e.preventDefault();
                                                e.stopPropagation();
                                                // 刷新文件
                                                store.code.resetStatic();
                                            }}
                                        />
                                    </div>
                                )
                            }
                            return title;
                        }
                    }}
                    extra={(
                        <Space key="0">
                            {/* <Button type="primary" size="small" key="3"
                                onClick={() => {
                                    store.updatePageElement();
                                    !store.right && store.setRight(true);
                                }}
                            >
                                预览
                            </Button> */}
                            <Checkbox checked={store.autosave}
                                onChange={store.setAutoSave}
                            >
                                自动保存
                            </Checkbox>
                            <Dropdown.Button
                                type={store.right? 'primary': 'default'}
                                size="small"
                                onClick={() => {
                                    store.updatePageElement();
                                    Promise.all([
                                        pageStore.getOneMenu(),
                                        plugins.init(),
                                        language.reloadAppPlugins(),
                                    ]).then(() => {
                                        store.setRight(!store.right);
                                    })
                                }}
                                droplist={(
                                    <Menu>
                                        <Menu.Item key='1'
                                            onClick={() => {
                                                // store.updatePageElement();
                                                // const win = window.open(`#/dev-develop/${app.info.mark}`, '_blank') as any;
                                                // store.win = win;
                                                // Object.assign(win, {
                                                //     moduleStore,
                                                //     fileStore: file,
                                                //     app: app,
                                                //     language,
                                                //     pageStore: pageStore,
                                                // } as IfrmaeAppProps)
                                                window.open(`#/dev-preview/${app.info.mark}`, '_blank')
                                            }}
                                        >新窗口预览</Menu.Item>
                                    </Menu>
                                )}
                            >
                                预览
                            </Dropdown.Button>
                            <AsyncButton key="save" size="small" type="primary"
                                onClick={() => {
                                    return store.saveData();
                                }}
                            >
                                保存
                            </AsyncButton>
                            <Button type="primary" size="small" key="2"
                                onClick={() => {
                                    store.syncUpddatePageStore()
                                }}
                            >执行</Button>
                        </Space>
                    )}
                    right={
                        store.right ? (
                            <AppIframe />
                        )
                        : null
                    }
                />
                <AddModule
                    visible={visible}
                    onCancel={() => {
                        setVisible(false);
                    }}
                    onSuccess={async (moduleId) => {
                        await moduleStore.syncModuleIds([moduleId]);
                        await store.addTab(moduleId);   // 添加模块
                        store.setActiveTab(moduleId);   // 默认打开模块
                        await store.addModuleFile(moduleId);    // 添加模块到目录
                        Message.success("添加成功")
                        setVisible(false);
                    }}
                />
            </div >
        )
    })
}